int veces = 0;
const int PAUSA = 300;

void setup() {
  pinMode(LED_BUILTIN, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  veces = veces + 1;
  Serial.print("Encendido nro: ");
  Serial.println(veces);

  digitalWrite(LED_BUILTIN, HIGH);
  delay(PAUSA);
  digitalWrite(LED_BUILTIN, LOW);
  delay(PAUSA);
}

int ciclo = 0;

void setup() {
  pinMode(LED_BUILTIN, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  ciclo++;
  int pausa;

  if (ciclo <= 10) {
    pausa = 120; // rápido
    Serial.println("Modo RAPIDO");
  } else {
    pausa = 500; // lento
    Serial.println("Modo LENTO");
  }

  digitalWrite(LED_BUILTIN, HIGH);
  delay(pausa);
  digitalWrite(LED_BUILTIN, LOW);
  delay(pausa);

  if (ciclo >= 20) {
    ciclo = 0; // reinicia el patrón
  }
}

void destello() {
  digitalWrite(LED_BUILTIN, HIGH);
  delay(150);
  digitalWrite(LED_BUILTIN, LOW);
  delay(150);
}

void setup() {
  pinMode(LED_BUILTIN, OUTPUT);
}

void loop() {
  for (int i = 0; i < 3; i++) {
    destello();
  }
  delay(1000); // pausa larga entre grupos
}

void punto() {
  digitalWrite(LED_BUILTIN, HIGH);
  delay(180);
  digitalWrite(LED_BUILTIN, LOW);
  delay(180);
}

void raya() {
  digitalWrite(LED_BUILTIN, HIGH);
  delay(500);
  digitalWrite(LED_BUILTIN, LOW);
  delay(180);
}

void letraS() {
  punto(); punto(); punto();
  delay(400);
}

void letraO() {
  raya(); raya(); raya();
  delay(400);
}

void setup() {
  pinMode(LED_BUILTIN, OUTPUT);
}

void loop() {
  letraS();
  letraO();
  letraS();
  delay(1500);
}
